O que o botão mostra depois de **três cliques**?

```jsx
import { useState } from 'react'

function Contador() {
  const [contador, setContador] = useState(0)

  return (
    <button onClick={() => setContador(contador + 1)}>
      Cliques: {contador}
    </button>
  )
}
```

Neste botão, o número fica guardado numa variável comum:

```jsx
let cliques = 0

function ContadorComum() {
  function contar() {
    cliques = cliques + 1
    console.log(cliques)
  }

  return <button onClick={contar}>Cliques: {cliques}</button>
}
```

